export default AdminPage;

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getTags, createTag, updateTag, deleteTag } from '../../services/adminService';
import { Tag, TagCreate } from '../../types/tag';
import { 
    Box, Typography, List, ListItem, ListItemText, ListItemSecondaryAction, 
    IconButton, TextField, Button, Dialog, DialogTitle, DialogContent, 
    DialogActions, Alert, CircularProgress, Chip,
    InputAdornment, FormControl, InputLabel, OutlinedInput
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import CheckIcon from '@mui/icons-material/Check';
import CloseIcon from '@mui/icons-material/Close';
import ColorLensIcon from '@mui/icons-material/ColorLens';

const TagManagement: React.FC = () => {
    const queryClient = useQueryClient();
    const { data: tags, isLoading, error } = useQuery<Tag[]>({
        queryKey: ['tags'],
        queryFn: getTags,
    });

    const [openDialog, setOpenDialog] = useState(false);
    const [editingTag, setEditingTag] = useState<Tag | null>(null);
    const [tagName, setTagName] = useState('');
    const [tagColor, setTagColor] = useState('');
    const [formError, setFormError] = useState<string | null>(null);

    const addTagMutation = useMutation({
        mutationFn: (newTag: TagCreate) => createTag(newTag),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['tags'] });
            handleCloseDialog();
        },
        onError: (err: any) => setFormError(err.response?.data?.detail || 'Failed to add tag.'),
    });

    const updateTagMutation = useMutation({
        mutationFn: (data: { id: number; tag: TagCreate }) => updateTag(data.id, data.tag),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['tags'] });
            handleCloseDialog();
        },
        onError: (err: any) => setFormError(err.response?.data?.detail || 'Failed to update tag.'),
    });

    const deleteTagMutation = useMutation({
        mutationFn: (id: number) => deleteTag(id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['tags'] });
        },
        onError: (err: any) => alert(err.response?.data?.detail || 'Failed to delete tag.'),
    });

    const handleOpenDialog = (tag: Tag | null = null) => {
        setEditingTag(tag);
        setTagName(tag ? tag.name : '');
        setTagColor(tag ? tag.color || '' : '');
        setFormError(null);
        setOpenDialog(true);
    };

    const handleCloseDialog = () => {
        setOpenDialog(false);
        setEditingTag(null);
        setTagName('');
        setTagColor('');
        setFormError(null);
    };

    const handleSubmit = () => {
        if (!tagName.trim()) {
            setFormError('Tag name cannot be empty.');
            return;
        }
        const tagData: TagCreate = { name: tagName.trim(), color: tagColor.trim() || undefined };

        if (editingTag) {
            updateTagMutation.mutate({ id: editingTag.id, tag: tagData });
        } else {
            addTagMutation.mutate(tagData);
        }
    };

    const handleDelete = (id: number) => {
        if (window.confirm('Are you sure you want to delete this tag?')) {
            deleteTagMutation.mutate(id);
        }
    };

    if (isLoading) {
        return <CircularProgress />;
    }

    if (error) {
        return <Alert severity="error">Error loading tags: {error.message}</Alert>;
    }

    return (
        <Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h5" gutterBottom>Tags</Typography>
                <Button 
                    variant="contained" 
                    startIcon={<AddIcon />} 
                    onClick={() => handleOpenDialog()}
                >
                    Add Tag
                </Button>
            </Box>
            <List component="nav">
                {tags?.map((tag) => (
                    <ListItem 
                        key={tag.id} 
                        sx={{ border: '1px solid #eee', borderRadius: 1, mb: 1 }}
                    >
                        <Chip label={tag.name} size="small" sx={{ 
                            bgcolor: tag.color || '#e0e0e0', 
                            color: tag.color ? 'white' : 'black',
                            mr: 2
                        }} />
                        <ListItemText primary={tag.name} secondary={tag.color || 'No color'} />
                        <ListItemSecondaryAction>
                            <IconButton edge="end" aria-label="edit" onClick={() => handleOpenDialog(tag)}>
                                <EditIcon />
                            </IconButton>
                            <IconButton edge="end" aria-label="delete" onClick={() => handleDelete(tag.id)}>
                                <DeleteIcon />
                            </IconButton>
                        </ListItemSecondaryAction>
                    </ListItem>
                ))}
            </List>

            <Dialog open={openDialog} onClose={handleCloseDialog}>
                <DialogTitle>{editingTag ? 'Edit Tag' : 'Add New Tag'}</DialogTitle>
                <DialogContent>
                    {formError && <Alert severity="error" sx={{ mb: 2 }}>{formError}</Alert>}
                    <TextField
                        autoFocus
                        margin="dense"
                        label="Tag Name"
                        type="text"
                        fullWidth
                        variant="outlined"
                        value={tagName}
                        onChange={(e) => setTagName(e.target.value)}
                        sx={{ mb: 2 }}
                    />
                    <FormControl fullWidth margin="dense" variant="outlined">
                        <InputLabel htmlFor="tag-color">Tag Color (Hex or Name)</InputLabel>
                        <OutlinedInput
                            id="tag-color"
                            value={tagColor}
                            onChange={(e) => setTagColor(e.target.value)}
                            startAdornment={
                                <InputAdornment position="start">
                                    <ColorLensIcon sx={{ color: tagColor || '#9e9e9e' }} />
                                </InputAdornment>
                            }
                            label="Tag Color (Hex or Name)"
                        />
                    </FormControl>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleCloseDialog} startIcon={<CloseIcon />}>Cancel</Button>
                    <Button 
                        onClick={handleSubmit} 
                        color="primary" 
                        variant="contained"
                        disabled={addTagMutation.isPending || updateTagMutation.isPending}
                        startIcon={addTagMutation.isPending || updateTagMutation.isPending ? <CircularProgress size={20} /> : <CheckIcon />}
                    >
                        {editingTag ? 'Save Changes' : 'Add Tag'}
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default TagManagement;

import api from './api';
import { Tag, TagCreate } from '../types/tag';
import { Topic, TopicCreate } from '../types/topic';

// --- Tag Services ---
export const getTags = async (): Promise<Tag[]> => {
  const response = await api.get<Tag[]>('/admin/tags/');
  return response.data;
};

export const createTag = async (tagData: TagCreate): Promise<Tag> => {
  const response = await api.post<Tag>('/admin/tags/', tagData);
  return response.data;
};

export const updateTag = async (tagId: number, tagData: TagCreate): Promise<Tag> => {
  const response = await api.put<Tag>(`/admin/tags/${tagId}`, tagData);
  return response.data;
};

export const deleteTag = async (tagId: number): Promise<void> => {
  await api.delete(`/admin/tags/${tagId}`);
};

// --- Topic Services ---
export const getTopics = async (): Promise<Topic[]> => {
  const response = await api.get<Topic[]>('/admin/topics/');
  return response.data;
};

export const createTopic = async (topicData: TopicCreate): Promise<Topic> => {
  const response = await api.post<Topic>('/admin/topics/', topicData);
  return response.data;
};

export const updateTopic = async (topicId: number, topicData: TopicCreate): Promise<Topic> => {
  const response = await api.put<Topic>(`/admin/topics/${topicId}`, topicData);
  return response.data;
};

export const deleteTopic = async (topicId: number): Promise<void> => {
  await api.delete(`/admin/topics/${topicId}`);
};

