import React from 'react';
import {
    Autocomplete,
    TextField,
    createFilterOptions,
    Chip,
    CircularProgress
} from '@mui/material';

const filter = createFilterOptions<any>();

interface CreatableAutocompleteProps {
    label: string;
    options: any[];
    value: any[];
    onChange: (newValue: any[]) => void;
    onCreateNew?: (name: string) => Promise<any>;
    getOptionLabel: (option: any) => string;
    placeholder?: string;
    loading?: boolean;
    disabled?: boolean;
    chipColorField?: string;
}

const CreatableAutocomplete: React.FC<CreatableAutocompleteProps> = ({
    label,
    options,
    value,
    onChange,
    onCreateNew,
    getOptionLabel,
    placeholder,
    loading,
    disabled,
    chipColorField
}) => {
    return (
        <Autocomplete
            multiple
            loading={loading}
            disabled={disabled}
            value={value}
            onChange={async (event, newValue) => {
                const processedValue: any[] = [];
                for (const item of newValue) {
                    if (typeof item === 'string') {
                        // This shouldn't happen with the filter logic below, but just in case
                        if (onCreateNew) {
                            const newItem = await onCreateNew(item);
                            processedValue.push(newItem);
                        }
                    } else if (item && item.inputValue) {
                        // Create a new value from the user input
                        if (onCreateNew) {
                            const newItem = await onCreateNew(item.inputValue);
                            processedValue.push(newItem);
                        }
                    } else {
                        processedValue.push(item);
                    }
                }
                onChange(processedValue);
            }}
            filterOptions={(options, params) => {
                const filtered = filter(options, params);

                const { inputValue } = params;
                // Suggest the creation of a new value
                const isExisting = options.some((option) => inputValue === getOptionLabel(option));
                if (inputValue !== '' && !isExisting && onCreateNew) {
                    filtered.push({
                        inputValue,
                        name: `Add "${inputValue}"`,
                    });
                }

                return filtered;
            }}
            selectOnFocus
            clearOnBlur
            handleHomeEndKeys
            id={`creatable-autocomplete-${label}`}
            options={options}
            getOptionLabel={(option) => {
                // Value selected with enter, right from the input
                if (typeof option === 'string') {
                    return option;
                }
                // Add "xxx" option created dynamically
                if (option.inputValue) {
                    return option.inputValue;
                }
                // Regular option
                return getOptionLabel(option);
            }}
            renderOption={(props, option) => <li {...props}>{option.name}</li>}
            freeSolo
            renderTags={(tagValue, getTagProps) =>
                tagValue.map((option, index) => (
                    <Chip
                        label={getOptionLabel(option)}
                        {...getTagProps({ index })}
                        sx={{
                            bgcolor: chipColorField && option[chipColorField] ? option[chipColorField] : undefined,
                            color: chipColorField && option[chipColorField] ? 'white' : 'inherit'
                        }}
                    />
                ))
            }
            renderInput={(params) => (
                <TextField
                    {...params}
                    label={label}
                    placeholder={placeholder}
                    InputProps={{
                        ...params.InputProps,
                        endAdornment: (
                            <React.Fragment>
                                {loading ? <CircularProgress color="inherit" size={20} /> : null}
                                {params.InputProps.endAdornment}
                            </React.Fragment>
                        ),
                    }}
                />
            )}
        />
    );
};

export default CreatableAutocomplete;

