import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getAllUsersAdmin, deleteUserAdmin } from '../../services/adminService';
import { 
    Box, Typography, List, ListItem, ListItemText, ListItemSecondaryAction, 
    IconButton, Alert, CircularProgress, Paper
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';

const UserManagement: React.FC = () => {
    const queryClient = useQueryClient();
    const { data: users, isLoading, error } = useQuery({
        queryKey: ['admin-users'],
        queryFn: getAllUsersAdmin,
    });

    const deleteMutation = useMutation({
        mutationFn: (id: number) => deleteUserAdmin(id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['admin-users'] });
        },
        onError: (err: any) => alert(err.response?.data?.detail || 'Failed to delete user.'),
    });

    const handleDelete = (id: number) => {
        if (window.confirm('Are you sure you want to delete this user? This action is irreversible.')) {
            deleteMutation.mutate(id);
        }
    };

    if (isLoading) return <CircularProgress />;
    if (error) return <Alert severity="error">Error loading users: {(error as any).message}</Alert>;

    return (
        <Box>
            <Typography variant="h6" gutterBottom>User Management</Typography>
            <List>
                {users?.map((user: any) => (
                    <Paper key={user.id} sx={{ mb: 1 }}>
                        <ListItem>
                            <ListItemText 
                                primary={`${user.name || ''} ${user.surname || ''} (${user.email})`} 
                                secondary={`ID: ${user.id} | Status: ${user.is_active ? 'Active' : 'Inactive'} | Superuser: ${user.is_superuser ? 'Yes' : 'No'}`} 
                            />
                            <ListItemSecondaryAction>
                                <IconButton edge="end" aria-label="delete" onClick={() => handleDelete(user.id)} color="error">
                                    <DeleteIcon />
                                </IconButton>
                            </ListItemSecondaryAction>
                        </ListItem>
                    </Paper>
                ))}
            </List>
        </Box>
    );
};

