          <Typography variant="body1" color="text.secondary">
            {project.description}
          </Typography>

          {/* Tags */}
          {project.tags && project.tags.length > 0 && (
            <Box sx={{ mt: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
