import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { 
    getTaskById, 
    getTaskDependencies, 
    getTaskComments, 
    createTaskComment,
} from '../services/tasks';
import { getUsers } from '../services/users';
import {
  Container,
  Typography,
  CircularProgress,
  Alert,
  Box,
  Paper,
  Grid,
  Chip,
  Avatar,
  AvatarGroup,
  List,
  ListItem,
  ListItemText,
  Divider,
  TextField,
  Button,
  Tab,
  Tabs,
  ListItemIcon,
  IconButton // Import IconButton for edit button
} from '@mui/material';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import LinkIcon from '@mui/icons-material/Link';
import CommentIcon from '@mui/icons-material/Comment';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import EditIcon from '@mui/icons-material/Edit'; // Import EditIcon
import { Task as TaskType } from '../types/task'; // Use specific TaskType
import { Tag } from '../types/tag';
import { Topic } from '../types/topic';
import EditTaskModal from '../components/tasks/EditTaskModal'; // Import EditTaskModal

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

const TaskDetailPage = () => {
  const { taskId } = useParams<{ taskId: string }>();
  const queryClient = useQueryClient();
  const [tabValue, setTabValue] = useState(0);
  const [newComment, setNewComment] = useState('');
  const [isEditTaskModalOpen, setIsEditTaskModalOpen] = useState(false); // State for Edit Task Modal

  const { data: task, isLoading, error } = useQuery<TaskType>({ // Use TaskType here
    queryKey: ['task', taskId],
    queryFn: () => getTaskById(taskId!),
    enabled: !!taskId,
  });

  const { data: users = [] } = useQuery({
    queryKey: ['users'],
    queryFn: getUsers,
  });

  const { data: dependencies = [] } = useQuery({
    queryKey: ['taskDependencies', taskId],
    queryFn: () => getTaskDependencies(taskId!),
    enabled: !!taskId,
  });

  const { data: comments = [] } = useQuery({
    queryKey: ['taskComments', taskId],
    queryFn: () => getTaskComments(taskId!),
    enabled: !!taskId,
  });

  const commentMutation = useMutation({
    mutationFn: (content: string) => createTaskComment(Number(taskId), content),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['taskComments', taskId] });
      setNewComment('');
    },
  });

  const handleCommentSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newComment.trim()) {
      commentMutation.mutate(newComment);
    }
  };

  const getUserName = (id: number) => {
    const user = users.find((u: any) => u.id === id);
    return user ? user.email : 'Unknown User';
  };

  if (isLoading) return <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}><CircularProgress /></Box>;
  if (error) return <Alert severity="error">Error loading task details.</Alert>;
  if (!task) return <Alert severity="warning">Task not found.</Alert>;

  const promoter = users.find((u: any) => u.id === task.promoter_id);

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Paper elevation={3} sx={{ p: 4 }}>
        {/* Header */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
            <Box>
                <Typography variant="h4" component="h1" gutterBottom>
                {task.name}
                </Typography>
                <Typography variant="subtitle1" color="text.secondary">
                ID: {task.id} | Status: <Chip label={task.status} size="small" color={task.status === 'Completed' ? 'success' : 'default'} />
                </Typography>

                {/* Tags */}
                {task.tags && task.tags.length > 0 && (
                    <Box sx={{ mt: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                    {task.tags.map((tag: Tag) => (
                        <Chip
                        key={tag.id}
                        label={tag.name}
                        size="small"
                        sx={{ bgcolor: tag.color || undefined, color: tag.color ? 'white' : 'black' }}
                        />
                    ))}
                    </Box>
                )}

                {/* Topics */}
                {task.topics && task.topics.length > 0 && (
                    <Box sx={{ mt: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                    {task.topics.map((topic: Topic) => (
                        <Chip key={topic.id} label={topic.name} size="small" variant="outlined" />
                    ))}
                    </Box>
                )}
            </Box>
            <Box sx={{ textAlign: 'right' }}>
                 <Typography variant="caption" display="block" color="text.secondary">Due Date</Typography>
                 <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <CalendarTodayIcon fontSize="small" color="action" />
                    <Typography variant="body1">
                        {task.end_date ? new Date(task.end_date).toLocaleDateString() : 'No due date'}
                    </Typography>
                 </Box>
                 <IconButton color="primary" onClick={() => setIsEditTaskModalOpen(true)} sx={{ mt: 1 }}>
                    <EditIcon />
                 </IconButton>
            </Box>
        </Box>

        <Divider sx={{ mb: 3 }} />

        <Grid container spacing={4}>
            {/* Left Column: Details */}
            <Grid item xs={12} md={8}>
                <Typography variant="h6" gutterBottom>Description</Typography>
                <Typography variant="body1" paragraph>
                    {task.description || 'No description provided.'}
                </Typography>

                <Box sx={{ width: '100%', mt: 4 }}>
                    <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
                        <Tabs value={tabValue} onChange={(_, v) => setTabValue(v)}>
                            <Tab label={`Subtasks (${task.subtasks?.length || 0})`} />
                            <Tab label={`Comments (${comments.length})`} />
                            <Tab label={`Dependencies (${dependencies.length})`} />
                            <Tab label="Attachments" />
                        </Tabs>
                    </Box>

                    {/* Subtasks Tab */}
                    <TabPanel value={tabValue} index={0}>
                        <List>
                            {task.subtasks && task.subtasks.length > 0 ? (
                                task.subtasks.map((sub: any) => (
                                    <ListItem key={sub.id} disableGutters divider>
                                        <ListItemIcon>
                                            <CheckCircleIcon color={sub.status === 'Completed' ? 'success' : 'disabled'} />
                                        </ListItemIcon>
                                        <ListItemText 
                                            primary={sub.name} 
                                            secondary={
                                                <React.Fragment>
                                                    <Typography variant="caption" component="span" sx={{ display: 'block' }}>
                                                        {sub.status}
                                                    </Typography>
                                                    {sub.start_date && sub.end_date && (
                                                        <Typography variant="caption" component="span">
                                                            {new Date(sub.start_date).toLocaleDateString()} - {new Date(sub.end_date).toLocaleDateString()}
                                                        </Typography>
                                                    )}
                                                </React.Fragment>
                                            }
                                        />
                                    </ListItem>
                                ))
                            ) : (
                                <Typography color="text.secondary">No subtasks.</Typography>
                            )}
                        </List>
                    </TabPanel>

                    {/* Comments Tab */}
                    <TabPanel value={tabValue} index={1}>
                        <List sx={{ mb: 2 }}>
                            {comments.map((comment: any) => (
                                <ListItem key={comment.id} alignItems="flex-start" divider>
                                    <ListItemText
                                        primary={getUserName(comment.owner_id)}
                                        secondary={
                                            <React.Fragment>
                                                <Typography component="span" variant="body2" color="text.primary">
                                                    {comment.content}
                                                </Typography>
                                                <br />
                                                <Typography variant="caption">
                                                    {new Date(comment.created_at).toLocaleString()}
                                                </Typography>
                                            </React.Fragment>
                                        }
                                    />
                                </ListItem>
                            ))}
                        </List>
                        <form onSubmit={handleCommentSubmit}>
                            <TextField
                                fullWidth
                                multiline
                                rows={3}
                                variant="outlined"
                                placeholder="Add a comment..."
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                sx={{ mb: 1 }}
                            />
                            <Button type="submit" variant="contained" endIcon={<CommentIcon />}>
                                Post Comment
                            </Button>
                        </form>
                    </TabPanel>

                    {/* Dependencies Tab */}
                    <TabPanel value={tabValue} index={2}>
                        <List>
                            {dependencies.map((dep: any) => (
                                <ListItem key={dep.id}>
                                    <ListItemIcon><LinkIcon /></ListItemIcon>
                                    <ListItemText 
                                        primary={`Depends on: ${dep.prerequisite_id ? `Task #${dep.prerequisite_id}` : `Subtask #${dep.prerequisite_subtask_id}`}`} 
                                    />
                                </ListItem>
                            ))}
                            {dependencies.length === 0 && <Typography color="text.secondary">No dependencies.</Typography>}
                        </List>
                        {/* TODO: Add 'Add Dependency' UI */}
                    </TabPanel>

                     {/* Attachments Tab */}
                     <TabPanel value={tabValue} index={3}>
                        <Typography color="text.secondary">No attachments (Upload not implemented yet).</Typography>
                    </TabPanel>
                </Box>
            </Grid>

            {/* Right Column: People & Meta */}
            <Grid item xs={12} md={4}>
                <Paper variant="outlined" sx={{ p: 2, mb: 2 }}>
                    <Typography variant="subtitle2" color="text.secondary" gutterBottom>Owner</Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                        <Avatar sx={{ width: 32, height: 32 }}>{getUserName(task.owner_id)[0].toUpperCase()}</Avatar>
                        <Typography variant="body2">{getUserName(task.owner_id)}</Typography>
                    </Box>

                    <Typography variant="subtitle2" color="text.secondary" gutterBottom>Promoter / Lead</Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                        {promoter ? (
                            <>
                                <Avatar sx={{ width: 32, height: 32, bgcolor: 'secondary.main' }}>{promoter.email[0].toUpperCase()}</Avatar>
                                <Typography variant="body2">{promoter.email}</Typography>
                            </>
                        ) : (
                            <Typography variant="body2" color="text.secondary">Not assigned</Typography>
                        )}
                    </Box>

                    <Typography variant="subtitle2" color="text.secondary" gutterBottom>Assignees (Team)</Typography>
                    {task.assignees && task.assignees.length > 0 ? (
                        <AvatarGroup max={4} sx={{ justifyContent: 'flex-start' }}>
                            {task.assignees.map((user: any) => (
                                <Avatar key={user.id} alt={user.email} title={user.email}>
                                    {user.email[0].toUpperCase()}
                                </Avatar>
                            ))}
                        </AvatarGroup>
                    ) : (
                        <Typography variant="body2" color="text.secondary">No team members assigned</Typography>
                    )}
                </Paper>
            </Grid>
        </Grid>
      </Paper>
      {task && (
          <EditTaskModal
              open={isEditTaskModalOpen}
              onClose={() => setIsEditTaskModalOpen(false)}
              task={task}
              onTaskUpdated={() => {
                  queryClient.invalidateQueries({ queryKey: ['task', taskId] });
                  setIsEditTaskModalOpen(false);
              }}
          />
      )}
    </Container>
  );
};

